  3	
  4	namespace Relay.Infrastructure.Tests.Schema;
  5	
  6	[Collection(SqlServerTestGroup.Name)]
  7	public sealed class InitialCreateSchemaTests(SqlServerFixture fixture) : SqlServerTest(fixture)
  8	{
  9	    [Fact]
 10	    public async Task InitialCreateAccountOccurredIndexHasAccountThenOccurredAtKeys()
 11	    {
 12	        var keyColumns = await QueryDbContext.Database.SqlQuery<string>($"""
 13	            SELECT indexed_column.name AS Value
 14	            FROM sys.indexes AS table_index
 15	            JOIN sys.index_columns AS index_column
 16	              ON index_column.object_id = table_index.object_id AND index_column.index_id = table_index.index_id
 17	            JOIN sys.columns AS indexed_column
 18	              ON indexed_column.object_id = index_column.object_id AND indexed_column.column_id = index_column.column_id
 19	            WHERE table_index.object_id = OBJECT_ID(N'dbo.activity_events')
 20	              AND table_index.name = N'IX_activity_events_account_occurred'
 21	              AND index_column.is_included_column = 0
 22	            ORDER BY index_column.key_ordinal
 23	            """).ToListAsync(CancellationToken);
 24	
 25	        keyColumns.ShouldBe(["account_id", "occurred_at"]);
 26	    }
 27	
 28	    [Fact]
 29	    public async Task InitialCreateAccountOccurredIndexIncludesEveryDeduplicationColumn()
 30	    {
 31	        var includedColumns = await QueryDbContext.Database.SqlQuery<string>($"""
 32	            SELECT indexed_column.name AS Value
 33	            FROM sys.indexes AS table_index
 34	            JOIN sys.index_columns AS index_column
 35	              ON index_column.object_id = table_index.object_id AND index_column.index_id = table_index.index_id
 36	            JOIN sys.columns AS indexed_column
 37	              ON indexed_column.object_id = index_column.object_id AND indexed_column.column_id = index_column.column_id
 38	            WHERE table_index.object_id = OBJECT_ID(N'dbo.activity_events')
 39	              AND table_index.name = N'IX_activity_events_account_occurred'
 40	              AND index_column.is_included_column = 1
 41	            """).ToListAsync(CancellationToken);
 42	
 43	        includedColumns.ShouldBe(["location", "event_type", "duration_seconds", "outcome"], ignoreOrder: true);
 44	    }
 45	
 46	    [Fact]
 47	    public async Task InitialCreateActivityEventsHasNoUniqueIndexOtherThanPrimaryKey()
 48	    {
 49	        var uniqueNonPrimaryIndexCounts = await QueryDbContext.Database.SqlQuery<int>($"""
 50	            SELECT COUNT(*) AS Value
 51	            FROM sys.indexes
 52	            WHERE object_id = OBJECT_ID(N'dbo.activity_events')
 53	              AND is_unique = 1
 54	              AND is_primary_key = 0
 55	            """).ToListAsync(CancellationToken);
 56	
 57	        uniqueNonPrimaryIndexCounts.ShouldBe([0]);
 58	    }
 59	}
