  9	[Collection(SeededApiTestGroup.Name)]
 10	public sealed class SeedLoadTests(SeededApiFixture fixture) : SeededApiTest(fixture)
 11	{
 12	    private const int WeeksFromJanuary26ThroughJuly27 = 27;
 13	
 14	    private static readonly DateOnly FirstSeedWeek = new(2026, 1, 26);
 15	
 16	    [Fact]
 17	    public async Task SeedMigrationLoadsTwentyAccounts()
 18	    {
 19	        await using var dbContext = Fixture.CreateSeededDbContext();
 20	
 21	        (await dbContext.Accounts.CountAsync(CancellationToken)).ShouldBe(20);
 22	    }
 23	
 24	    [Fact]
 25	    public async Task SeedMigrationLoadsEveryRawEventIncludingDuplicates()
 26	    {
 27	        await using var dbContext = Fixture.CreateSeededDbContext();
 28	
 29	        (await dbContext.ActivityEvents.CountAsync(CancellationToken)).ShouldBe(12626);
 30	    }
 31	
 32	    [Fact]
 33	    public async Task SeedMigrationKeepsBothRawRowsOfTheAccount1SiteCDuplicate()
 34	    {
 35	        var chicagoWeekOfJuly6StartUtc = new DateTime(2026, 7, 6, 5, 0, 0, DateTimeKind.Utc);
 36	        var chicagoWeekOfJuly6EndUtc = new DateTime(2026, 7, 13, 5, 0, 0, DateTimeKind.Utc);
 37	        await using var dbContext = Fixture.CreateSeededDbContext();
 38	
 39	        var rawRows = await dbContext.ActivityEvents.CountAsync(
 40	            activityEvent => activityEvent.AccountId == 1
 41	                && activityEvent.Location == "Site C"
 42	                && activityEvent.OccurredAt >= chicagoWeekOfJuly6StartUtc
 43	                && activityEvent.OccurredAt < chicagoWeekOfJuly6EndUtc,
 44	            CancellationToken);
 45	
 46	        rawRows.ShouldBe(5);
 47	    }
 48	
 49	    [Fact]
 50	    public async Task CountWeeklyBySiteAccount1SiteCWeekOfJuly6CountsTheExactDuplicateOnce()
 51	    {
 52	        await using var scope = Fixture.Factory.Services.CreateAsyncScope();
 53	        var weekCalendar = scope.ServiceProvider.GetRequiredService<IWeekCalendar>();
 54	        var activityQueries = scope.ServiceProvider.GetRequiredService<IActivityQueries>();
 55	        var weekOfJuly6 = weekCalendar.Window(new DateOnly(2026, 7, 6), "America/Chicago");
 56	
 57	        var weeklyCounts = await activityQueries.CountWeeklyBySiteAsync(1, [weekOfJuly6], ActivityType.All, CancellationToken);
 58	
 59	        weeklyCounts.Single(weeklyCount => weeklyCount.Location == "Site C").Count.ShouldBe(4);
 60	    }
 61	
