 81	    [InlineData(19, 210)]
 82	    [InlineData(20, 0)]
 83	    public async Task CountWeeklyBySiteEveryWeekOfTheSeedSumsToTheDeduplicatedAccountTotal(int accountId, int expectedDeduplicatedEvents)
 84	    {
 85	        var deduplicatedEvents = await CountDeduplicatedEventsAcrossTheSeedAsync(accountId);
 86	
 87	        deduplicatedEvents.ShouldBe(expectedDeduplicatedEvents);
 88	    }
 89	
 90	    [Fact]
 91	    public async Task CountWeeklyBySiteEveryAccountAndWeekSumsTo12614()
 92	    {
 93	        var deduplicatedEvents = 0;
 94	        for (var accountId = 1; accountId <= 20; accountId++)
 95	        {
 96	            deduplicatedEvents += await CountDeduplicatedEventsAcrossTheSeedAsync(accountId);
 97	        }
 98	
 99	        deduplicatedEvents.ShouldBe(12614);
100	    }
101	
102	    [Fact]
103	    public async Task ListSiteFirstActivitiesAccount14SitesStartInTheGoldenWeeks()
104	    {
105	        await using var scope = Fixture.Factory.Services.CreateAsyncScope();
106	        var weekCalendar = scope.ServiceProvider.GetRequiredService<IWeekCalendar>();
107	        var activityQueries = scope.ServiceProvider.GetRequiredService<IActivityQueries>();
108	
109	        var siteFirstActivities = await activityQueries.ListSiteFirstActivitiesAsync(14, CancellationToken);
110	
111	        siteFirstActivities
112	            .Select(site => (site.Location, FirstWeek: weekCalendar.WeekContaining(site.FirstActivityUtc, "America/New_York")))
113	            .ShouldBe(
114	                [
115	                    ("Site A", new DateOnly(2026, 2, 2)),
116	                    ("Site B", new DateOnly(2026, 1, 26)),
117	                    ("Site C", new DateOnly(2026, 2, 2)),
118	                    ("Site D", new DateOnly(2026, 1, 26)),
119	                ],
120	                ignoreOrder: true);
121	    }
122	
123	    private async Task<int> CountDeduplicatedEventsAcrossTheSeedAsync(int accountId)
124	    {
125	        await using var scope = Fixture.Factory.Services.CreateAsyncScope();
126	        var weekCalendar = scope.ServiceProvider.GetRequiredService<IWeekCalendar>();
127	        var accountQueries = scope.ServiceProvider.GetRequiredService<IAccountQueries>();
128	        var activityQueries = scope.ServiceProvider.GetRequiredService<IActivityQueries>();
129	        var account = (await accountQueries.FindAsync(accountId, CancellationToken)).ShouldNotBeNull();
130	        var seedWeekWindows = Enumerable.Range(0, WeeksFromJanuary26ThroughJuly27)
131	            .Select(weekIndex => weekCalendar.Window(FirstSeedWeek.AddDays(7 * weekIndex), account.Timezone))
132	            .ToList();
133	
134	        var weeklyCounts = await activityQueries.CountWeeklyBySiteAsync(accountId, seedWeekWindows, ActivityType.All, CancellationToken);
135	
136	        return weeklyCounts.Sum(weeklyCount => weeklyCount.Count);
137	    }
138	}
