    private static readonly string[] LocationPropertyOrder = ["location", "count", "baseline", "status", "deviation"];
    private static readonly string[] BaselinePropertyNames = ["weeksUsed", "median", "low", "high"];

    [Fact]
    public async Task GetActivityHealthTopLevelHasExactlyTheContractProperties()
    {
        var report = await GetReportAsync(DefaultAccountPath);

        PropertyNames(report.Root).ShouldBe(TopLevelPropertyNames, ignoreOrder: true);
    }

    [Fact]
    public async Task GetActivityHealthAccountHasIdNameAndTimezone()
    {
        var report = await GetReportAsync(DefaultAccountPath);

        var account = report.Root.GetProperty("account");
        PropertyNames(account).ShouldBe(["id", "name", "timezone"], ignoreOrder: true);
        account.GetProperty("id").GetInt32().ShouldBe(14);
        account.GetProperty("name").GetString().ShouldBe("Beacon Home Security");
        account.GetProperty("timezone").GetString().ShouldBe("America/New_York");
    }

    [Fact]
    public async Task GetActivityHealthWeekHasStartAndEnd()
    {
        var report = await GetReportAsync(DefaultAccountPath);

        PropertyNames(report.Root.GetProperty("week")).ShouldBe(["start", "end"], ignoreOrder: true);
    }

    [Fact]
    public async Task GetActivityHealthSummaryHasSeriesPropertiesWithoutLocation()
    {
        var report = await GetReportAsync(DefaultAccountPath);

        PropertyNames(report.Root.GetProperty("summary")).ShouldBe(SeriesPropertyNames, ignoreOrder: true);
    }

    [Fact]
    public async Task GetActivityHealthBaselineHasWeeksUsedMedianLowHigh()
    {
        var report = await GetReportAsync(DefaultAccountPath);

        PropertyNames(report.Root.GetProperty("summary").GetProperty("baseline")).ShouldBe(BaselinePropertyNames, ignoreOrder: true);
        foreach (var location in report.Root.GetProperty("locations").EnumerateArray())
        {
            PropertyNames(location.GetProperty("baseline")).ShouldBe(BaselinePropertyNames, ignoreOrder: true);
        }
    }

    [Fact]
    public async Task GetActivityHealthLocationPropertiesAreInContractOrder()
    {
        var report = await GetReportAsync(Account6ExamplePath);

        var locations = report.Root.GetProperty("locations").EnumerateArray().ToList();
        locations.Count.ShouldBe(15);
        foreach (var location in locations)
        {
            PropertyNames(location).ShouldBe(LocationPropertyOrder);
        }
    }

    [Fact]
    public async Task GetActivityHealthNumbersAreJsonNumbersComparedByValue()
    {
        var report = await GetReportAsync(Account6ExamplePath);

        var siteM = report.Root.GetProperty("locations")[0];
        siteM.GetProperty("deviation").ValueKind.ShouldBe(JsonValueKind.Number);
        siteM.GetProperty("deviation").GetDouble().ShouldBe(1.30, SeriesJson.Tolerance);
        var summaryMedian = report.Root.GetProperty("summary").GetProperty("baseline").GetProperty("median");
        summaryMedian.ValueKind.ShouldBe(JsonValueKind.Number);
        summaryMedian.GetDouble().ShouldBe(72.5, SeriesJson.Tolerance);
        report.Root.GetProperty("baselineWeeks").ValueKind.ShouldBe(JsonValueKind.Number);
        report.Root.GetProperty("summary").GetProperty("count").ValueKind.ShouldBe(JsonValueKind.Number);
    }

    [Fact]
    public async Task GetActivityHealthInsufficientBaselineKeepsNullPropertiesInTheBody()
        report.Summary.ShouldHaveDeviation(0.13);
    }

    [Fact]
    public async Task GetActivityHealthFoundReportRoundsLocationDeviationsAwayFromZero()
    {
        var (response, _) = await GetWithCannedResultAsync(new ActivityHealthResult.Found(MidpointReport), "/api/accounts/14/activity-health");

        var report = response.ShouldBeHealthReport();
        report.Location("Site B").ShouldHaveDeviation(-0.13);
        report.Location("Site A").ShouldHaveDeviation(0.13);
    }

    [Fact]
    public async Task GetActivityHealthFoundReportKeepsTheServiceLocationOrder()
    {
        var (response, _) = await GetWithCannedResultAsync(new ActivityHealthResult.Found(MidpointReport), "/api/accounts/14/activity-health");

        response.ShouldBeHealthReport().LocationNames.ShouldBe(["Site B", "Site A"]);
    }

    [Fact]
    public async Task GetActivityHealthFoundReportSerialisesCoreRecordsInContractShape()
    {
        var (response, _) = await GetWithCannedResultAsync(new ActivityHealthResult.Found(MidpointReport), "/api/accounts/14/activity-health");

        displayReport.Summary.Deviation.Value.ShouldBe(expectedDisplayDeviation, SeriesJson.Tolerance);
    }

    [Theory]
    [InlineData(0.125, 0.13)]
    [InlineData(-0.125, -0.13)]
    [InlineData(0.875, 0.88)]
    [InlineData(-0.375, -0.38)]
    public void WithDisplayDeviationsLocationRoundsToTwoDecimalsAwayFromZero(double fullPrecisionDeviation, double expectedDisplayDeviation)
    {
        var report = Report(SummaryWithDeviation(0), LocationWithDeviation("Site A", fullPrecisionDeviation));

        var displayReport = report.WithDisplayDeviations();

        displayReport.Locations[0].Deviation.ShouldNotBeNull();
        displayReport.Locations[0].Deviation!.Value.ShouldBe(expectedDisplayDeviation, SeriesJson.Tolerance);
    }

    [Fact]
    public void WithDisplayDeviationsNullDeviationStaysNull()
    {
        var report = Report(SummaryWithDeviation(null), LocationWithDeviation("Site A", null));

        var displayReport = report.WithDisplayDeviations();

        displayReport.Summary.Deviation.ShouldBeNull();
        displayReport.Locations[0].Deviation.ShouldBeNull();
    }

    [Fact]
    public void WithDisplayDeviationsKeepsLocationOrderAndEveryOtherLocationField()
    {
        var report = Report(
            SummaryWithDeviation(0.125),
            LocationWithDeviation("Site C", -0.125),
            LocationWithDeviation("Site A", 0.125),
            LocationWithDeviation("Site B", null));

        var displayReport = report.WithDisplayDeviations();

        displayReport.Locations.Select(location => location with { Deviation = null })
            .ShouldBe(report.Locations.Select(location => location with { Deviation = null }));
        displayReport.Locations[0].Deviation.ShouldNotBeNull().ShouldBe(-0.13, SeriesJson.Tolerance);
        displayReport.Locations[1].Deviation.ShouldNotBeNull().ShouldBe(0.13, SeriesJson.Tolerance);
        displayReport.Locations[2].Deviation.ShouldBeNull();
    }

    [Fact]
    public void WithDisplayDeviationsKeepsEveryNonDeviationReportField()
    {
        var report = Report(SummaryWithDeviation(0.125), LocationWithDeviation("Site A", 0.125));

        var displayReport = report.WithDisplayDeviations();

        (displayReport with { Summary = report.Summary, Locations = report.Locations }).ShouldBe(report);
        (displayReport.Summary with { Deviation = null }).ShouldBe(SummaryWithDeviation(null));
        displayReport.Summary.Deviation.ShouldNotBeNull().ShouldBe(0.13, SeriesJson.Tolerance);
    }

    [Fact]
    public void WithDisplayDeviationsLeavesTheFullPrecisionReportUnchanged()
    {
        var location = LocationWithDeviation("Site A", -0.125);
        var report = Report(SummaryWithDeviation(0.125), location);

        _ = report.WithDisplayDeviations();

        report.Summary.Deviation.ShouldBe(0.125);
        report.Locations.ShouldBe([location]);
        location.Deviation.ShouldBe(-0.125);
    }
}
